using Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration; using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationCapabilitySnapshotTests{static AstronomyKnowledgeFoundationCapabilityDescriptor D(AstronomyKnowledgeFoundationCapabilityKind k,string id,string code,int order)=>new(new(k,id),code,code,code,order,typeof(IDisposable),typeof(System.IO.MemoryStream),ServiceLifetime.Singleton);[Fact]public void Orders_projects_and_rejects_duplicates(){var input=new List<AstronomyKnowledgeFoundationCapabilityDescriptor>{D(AstronomyKnowledgeFoundationCapabilityKind.QueryExecution,"b","b",2),D(AstronomyKnowledgeFoundationCapabilityKind.TypedKnowledge,"a","a",1)};var s=new AstronomyKnowledgeFoundationCapabilitySnapshot(input);input.Clear();Assert.Equal(new[]{"a","b"},s.Capabilities.Select(x=>x.Id.Value));Assert.Single(s.TypedKnowledge);Assert.Throws<NotSupportedException>(()=>((IList<AstronomyKnowledgeFoundationCapabilityDescriptor>)s.Capabilities).Add(D(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"c","c",1)));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeFoundationCapabilitySnapshot([D(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x","a",1),D(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x","b",2)]));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeFoundationCapabilitySnapshot([D(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"x","a",1),D(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"y","a",2)]));Assert.Equal(0,new AstronomyKnowledgeFoundationCapabilitySnapshot([]).Capabilities.Count);}}
